-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/zones/Rabao/npcs/Leodarion.lua"]={["Path"]="scripts/zones/Rabao/npcs/Leodarion.lua",["SHA256"]="b8a43f16c4e7dea83d80203e8ea1c3626cb6ac2e4df9c4e58d97872dfb631631",["Text"]="-----------------------------------\n-- Area: Rabao\n--  NPC: Leodarion\n-- Involved in Quest: True Will\n-- !pos -50 8 41 247\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRUE_WILL) == xi.questStatus.QUEST_ACCEPTED then\n        local trueWillCS = player:getCharVar('trueWillCS')\n\n        if trueWillCS == 1 then\n            player:startEvent(97)\n        elseif trueWillCS == 2 and not player:hasKeyItem(xi.keyItem.LARGE_TRICK_BOX) then\n            player:startEvent(98)\n        elseif player:hasKeyItem(xi.keyItem.LARGE_TRICK_BOX) then\n            player:startEvent(99)\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 97 then\n        player:delKeyItem(xi.keyItem.OLD_TRICK_BOX)\n        player:setCharVar('trueWillCS', 2)\n    elseif csid == 99 then\n        if\n            npcUtil.completeQuest(player, xi.questLog.OUTLANDS, xi.quest.id.outlands.TRUE_WILL, {\n                item = 13782, -- Ninja Chainmail\n                fame = 20,\n                fameArea = xi.fameArea.NORG,\n                title = xi.title.PARAGON_OF_NINJA_EXCELLENCE,\n                var = 'trueWillCS'\n            })\n        then\n            player:delKeyItem(xi.keyItem.LARGE_TRICK_BOX)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Rabao/npcs/Rahi_Fohlatti.lua"]={["Path"]="scripts/zones/Rabao/npcs/Rahi_Fohlatti.lua",["SHA256"]="f2dfd90ac45a57fed32e9b13afed01b4e80e49dc8278829dbd69303301ed08a1",["Text"]="-----------------------------------\n-- Area: Rabao\n--  NPC: Rahi Fohlatti\n-- Starts Quest: Trial Size Trial by Wind\n-- !pos -17 7 -10 247\n-----------------------------------\nlocal ID = zones[xi.zone.RABAO]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        trade:hasItemQty(xi.item.MINI_TUNING_FORK_OF_WIND, 1) and\n        player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_SIZE_TRIAL_BY_WIND) == xi.questStatus.QUEST_ACCEPTED and\n        player:getMainJob() == xi.job.SMN\n    then\n        player:startEvent(109, 0, xi.item.MINI_TUNING_FORK_OF_WIND, 3, 20)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local trialSizeWind = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_SIZE_TRIAL_BY_WIND)\n\n    if\n        player:getMainLvl() >= 20 and\n        player:getMainJob() == xi.job.SMN and\n        trialSizeWind == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.SELBINA_RABAO) >= 2\n    then\n        --Requires player to be Summoner at least lvl 20\n        player:startEvent(108, 0, xi.item.MINI_TUNING_FORK_OF_WIND, 3, 20)     --mini tuning fork, zone, level\n    elseif trialSizeWind == xi.questStatus.QUEST_ACCEPTED then\n        local windFork = player:hasItem(xi.item.MINI_TUNING_FORK_OF_WIND)\n\n        if windFork then\n            player:startEvent(68) -- Dialogue given to remind player to be prepared\n        else\n            player:startEvent(112, 0, xi.item.MINI_TUNING_FORK_OF_WIND, 3, 20) -- Need another mini tuning fork\n        end\n    elseif trialSizeWind == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(111) -- Defeated Avatar\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 108 and option == 1 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MINI_TUNING_FORK_OF_WIND) --Mini tuning fork\n        else\n            player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_SIZE_TRIAL_BY_WIND)\n            player:addItem(xi.item.MINI_TUNING_FORK_OF_WIND)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MINI_TUNING_FORK_OF_WIND)\n        end\n    elseif csid == 112 and option == 1 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MINI_TUNING_FORK_OF_WIND) --Mini tuning fork\n        else\n            player:addItem(xi.item.MINI_TUNING_FORK_OF_WIND)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MINI_TUNING_FORK_OF_WIND)\n        end\n    elseif csid == 109 and option == 1 then\n        xi.teleport.to(player, xi.teleport.id.CLOISTER_OF_GALES)\n    end\nend\n\nreturn entity\n"},["scripts/zones/RuLude_Gardens/npcs/Laityn.lua"]={["Path"]="scripts/zones/RuLude_Gardens/npcs/Laityn.lua",["SHA256"]="149430abfe170bd15e56cca9c9e057e59bdd687e113088d7cdc4092f976e8863",["Text"]="-----------------------------------\n-- Area: Ru'Lude Gardens\n--  NPC: Laityn\n-- Involved In Quest: Recollections\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.RECOLLECTIONS) == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('recollectionsQuest') == 0\n    then\n        player:startEvent(10003) -- Option CS for \"Recollections\"\n    else\n        player:startEvent(10006)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 10003 then\n        player:setCharVar('recollectionsQuest', 1)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Selbina/npcs/Melyon.lua"]={["Path"]="scripts/zones/Selbina/npcs/Melyon.lua",["SHA256"]="8573a6dcaf2e334b4f3ada462a7c6707035ee37e35c911bf6ccdd4ce0dc35c6b",["Text"]="-----------------------------------\n-- Area: Selbina\n--  NPC: Melyon\n-- Starts and Finishes Quest: Only the Best (R)\n-- Involved in Quest: Riding on the Clouds\n-- !pos 25 -6 6 248\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ONLY_THE_BEST) ~= xi.questStatus.QUEST_AVAILABLE then\n        if npcUtil.tradeHas(trade, { { xi.item.LA_THEINE_CABBAGE, 5 } }) then -- La Theine Cabbage x5\n            player:startEvent(62, 0, xi.item.LA_THEINE_CABBAGE)\n        elseif npcUtil.tradeHas(trade, { { xi.item.EAR_OF_MILLIONCORN, 3 } }) then -- Millioncorn x3\n            player:startEvent(63, 0, xi.item.EAR_OF_MILLIONCORN)\n        elseif npcUtil.tradeHas(trade, xi.item.CLUMP_OF_BOYAHDA_MOSS) then -- Boyahda Moss x1\n            player:startEvent(64, 0, xi.item.CLUMP_OF_BOYAHDA_MOSS)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ONLY_THE_BEST) == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(60, 4366, 629, xi.item.CLUMP_OF_BOYAHDA_MOSS) -- Start quest \"Only the Best\"\n    else\n        player:startEvent(61, 4366, 629, xi.item.CLUMP_OF_BOYAHDA_MOSS) -- During & after completed quest \"Only the Best\"\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 60 and option == 10 then\n        player:addQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ONLY_THE_BEST)\n    elseif csid == 62 and option == 11 then\n        npcUtil.giveCurrency(player, 'gil', 100)\n        player:addFame(xi.fameArea.BASTOK, 4)\n        player:addFame(xi.fameArea.SANDORIA, 4)\n        player:completeQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ONLY_THE_BEST)\n        player:confirmTrade()\n    elseif csid == 63 and option == 12 then\n        npcUtil.giveCurrency(player, 'gil', 120)\n        player:addFame(xi.fameArea.BASTOK, 6)\n        player:addFame(xi.fameArea.SANDORIA, 6)\n        player:completeQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ONLY_THE_BEST)\n        player:confirmTrade()\n    elseif csid == 64 and option == 13 then\n        npcUtil.giveCurrency(player, 'gil', 600)\n        player:addFame(xi.fameArea.BASTOK, 8)\n        player:addFame(xi.fameArea.SANDORIA, 8)\n        player:completeQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ONLY_THE_BEST)\n        player:confirmTrade()\n    end\nend\n\nreturn entity\n"},["scripts/zones/Selbina/npcs/Romeo.lua"]={["Path"]="scripts/zones/Selbina/npcs/Romeo.lua",["SHA256"]="674a6fb04fae1030cc2084faed32d941fd25e734677fd01538b907ca1a752636",["Text"]="-----------------------------------\n-- Area: Selbina\n--  NPC: Romeo\n-- Starts and Finishes Quest: Donate to Recycling\n-- !pos -11 -11 -6 248\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.DONATE_TO_RECYCLING) == xi.questStatus.QUEST_ACCEPTED and\n        (\n            npcUtil.tradeHas(trade, { { xi.item.ONION_DAGGER, 5 } }) or\n            npcUtil.tradeHas(trade, { { xi.item.ONION_KNIFE, 5 } }) or\n            npcUtil.tradeHas(trade, { { xi.item.ONION_SWORD, 5 } }) or\n            npcUtil.tradeHas(trade, { { xi.item.ONION_ROD, 5 } }) or\n            npcUtil.tradeHas(trade, { { xi.item.ONION_STAFF, 5 } })\n        )\n    then\n        player:startEvent(21) -- Finish quest \"Donate to Recycling\"\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local donateToRecycling = player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.DONATE_TO_RECYCLING)\n\n    if donateToRecycling == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(20) -- Start quest \"Donate to Recycling\"\n    elseif donateToRecycling == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(22) -- During quest \"Donate to Recycling\"\n    else\n        player:startEvent(23) -- Standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 20 then\n        player:addQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.DONATE_TO_RECYCLING)\n    elseif\n        csid == 21 and\n        npcUtil.completeQuest(player, xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.DONATE_TO_RECYCLING, { item = xi.item.WASTEBASKET, title = xi.title.ECOLOGIST })\n    then\n        player:addFame(xi.fameArea.SANDORIA, 10)\n        player:addFame(xi.fameArea.BASTOK, 10)\n        player:confirmTrade()\n    end\nend\n\nreturn entity\n"},["scripts/zones/Selbina/npcs/Vuntar.lua"]={["Path"]="scripts/zones/Selbina/npcs/Vuntar.lua",["SHA256"]="b20502f788876795e74248160cc4d814500a19a53961be0bd3c5f6479ebb87e5",["Text"]="-----------------------------------\n-- Area: Selbina\n--  NPC: Vuntar\n-- Starts and Finishes Quest: Cargo (R)\n-- !pos 7 -2 -15 248\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.CARGO) ~= xi.questStatus.QUEST_AVAILABLE then\n        if GetSystemTime() > player:getCharVar('VuntarCanBuyItem_date') then\n            if npcUtil.tradeHas(trade, xi.item.ROLANBERRY_881_CE) then\n                player:startEvent(52, 1) -- Can Buy rolanberry (881 ce)\n            elseif npcUtil.tradeHas(trade, xi.item.ROLANBERRY_874_CE) then\n                player:startEvent(52, 2) -- Can Buy rolanberry (874 ce)\n            elseif npcUtil.tradeHas(trade, xi.item.ROLANBERRY_864_CE) then\n                player:startEvent(52, 3) -- Can Buy rolanberry (864 ce)\n            end\n        else\n            player:startEvent(1134, 4365) -- Can't buy rolanberrys\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getMainLvl() >= 20 and\n        player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.CARGO) == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(50, 4365) -- Start quest \"Cargo\"\n    elseif player:getMainLvl() < 20 then\n        player:startEvent(53) -- Dialog for low level or low fame\n    else\n        player:startEvent(51, 4365) -- During & after completed quest \"Cargo\"\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 50 then\n        player:addQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.CARGO)\n    elseif csid == 52 then\n        player:setCharVar('VuntarCanBuyItem_date', JstMidnight())\n\n        if player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.CARGO) == xi.questStatus.QUEST_ACCEPTED then\n            player:completeQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.CARGO)\n            player:addFame(xi.fameArea.SANDORIA, 15)\n            player:addFame(xi.fameArea.BASTOK, 15)\n        end\n\n        if option == 1 then\n            npcUtil.giveCurrency(player, 'gil', 800)\n            player:confirmTrade()\n        elseif option == 2 then\n            npcUtil.giveCurrency(player, 'gil', 2000)\n            player:confirmTrade()\n        elseif option == 3 then\n            npcUtil.giveCurrency(player, 'gil', 3000)\n            player:confirmTrade()\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Southern_San_dOria/npcs/Amaura.lua"]={["Path"]="scripts/zones/Southern_San_dOria/npcs/Amaura.lua",["SHA256"]="2b2df1f1b697fe6ee4dff627a45b38882534e01339c47d9ca5804d077ff3d77f",["Text"]="-----------------------------------\n-- Area: Southern San d'Oria\n-- NPC : Amaura\n-- Involved in Quest: The Medicine Woman, To Cure a Cough\n-- !pos -85 -6 89 230\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local toCureaCough = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.TO_CURE_A_COUGH)\n\n    if\n        player:getCharVar('DiaryPage') >= 3 or\n        toCureaCough == xi.questStatus.QUEST_ACCEPTED\n    then\n        if\n            not player:hasKeyItem(xi.keyItem.THYME_MOSS) and\n            not player:hasKeyItem(xi.keyItem.COUGH_MEDICINE)\n        then\n            player:startEvent(645) -- need thyme moss for cough med\n        elseif player:hasKeyItem(xi.keyItem.THYME_MOSS) then\n            player:startEvent(646) -- receive cough med for Nenne\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 645 then\n        player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.TO_CURE_A_COUGH)\n    elseif csid == 646 then\n        player:delKeyItem(xi.keyItem.THYME_MOSS)\n        npcUtil.giveKeyItem(player, xi.keyItem.COUGH_MEDICINE)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Southern_San_dOria/npcs/Amutiyaal.lua"]={["Path"]="scripts/zones/Southern_San_dOria/npcs/Amutiyaal.lua",["SHA256"]="428d800fb400185c9b7f8a26210ae80a9fedc2474885810cfea31b7681603f51",["Text"]="-----------------------------------\n-- Area: Southern San d'Oria\n--  NPC: Amutiyaal\n--  Warp NPC (Aht Urhgan)\n-- !pos 116 0.1 84 230\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        trade:getGil() == 300 and\n        trade:getItemCount() == 1 and\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.LURE_OF_THE_WILDCAT) == xi.questStatus.QUEST_COMPLETED and\n        player:getCurrentMission(xi.mission.log_id.TOAU) > xi.mission.id.toau.IMMORTAL_SENTRIES\n    then\n        -- Needs a check for at least traded an invitation card to Naja Salaheem\n        player:startEvent(881)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if player:getCurrentMission(xi.mission.log_id.TOAU) >= xi.mission.id.toau.PRESIDENT_SALAHEEM then\n        player:startEvent(880)\n    else\n        player:startEvent(816)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 881 then\n        player:tradeComplete()\n        xi.teleport.to(player, xi.teleport.id.WHITEGATE)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Southern_San_dOria/npcs/Balasiel.lua"]={["Path"]="scripts/zones/Southern_San_dOria/npcs/Balasiel.lua",["SHA256"]="3fad80550f76e2578e11a928860194bd0a4e7bbc0149710a95b979eedb872478",["Text"]="-----------------------------------\n-- Area: Southern San d'Oria (230)\n--  NPC: Balasiel\n-- Starts and Finishes: A Squire's Test, A Squire's Test II, A Knight's Test, Methods Create Madness\n-- !pos -136 -11 64 230\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.KNIGHT_STALKER) == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('KnightStalker_Progress') == 2\n    then\n        player:startEvent(63) -- DRG AF3 cutscene, doesn't appear to have a follow up.\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 63 then\n        player:setCharVar('KnightStalker_Progress', 3)\n    end\nend\n\n--    player:startEvent(32690)     -- starlight celebration\n\nreturn entity\n"},["scripts/zones/Southern_San_dOria/npcs/Celyddon.lua"]={["Path"]="scripts/zones/Southern_San_dOria/npcs/Celyddon.lua",["SHA256"]="9d9fcab3997a9468e32fd1b553c1694dc2400d3edb58ecf065ad3f9a7948e0ee",["Text"]="-----------------------------------\n-- Area: Southern San d'Oria\n--  NPC: Celyddon\n--  General Info NPC\n-- !pos -129 -6 90 230\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local aSquiresTest = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_SQUIRES_TEST)\n\n    if aSquiresTest == (xi.questStatus.QUEST_AVAILABLE) then\n        player:startEvent(618) -- im looking for the examiner\n    elseif aSquiresTest == (xi.questStatus.QUEST_ACCEPTED) then\n        player:startEvent(619) -- i found the examiner but said i had to use sword\n    else\n        player:startEvent(620) -- says i needs a revival tree root\n    end\nend\n\nreturn entity\n"},["scripts/zones/Southern_San_dOria/npcs/Chanpau.lua"]={["Path"]="scripts/zones/Southern_San_dOria/npcs/Chanpau.lua",["SHA256"]="34da5afd75a75330d8165410f9d77d069b2bfb001f41539d0cea00afd7fe64dd",["Text"]="-----------------------------------\n-- Area: Southern San d'Oria\n--  NPC: Chanpau\n-- Optional Involvement in Quest: A Squire's Test II\n-- !pos -152 -2 55 230\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_BRUGAIRE_CONSORTIUM) == xi.questStatus.QUEST_COMPLETED then\n        local fired = player:getCharVar('Fired')\n\n        if fired == 1 then\n            player:startEvent(567) -- i got fired in a day\n        else\n            player:startEvent(505) -- theres work ill go check it out\n        end\n    else\n        player:startEvent(566)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 505 then\n        player:setCharVar('Fired', 1)\n    end\nend\n\n-- for future use\n--    player:startEvent(32691) -- starlight celebration\n\nreturn entity\n"},["scripts/zones/Southern_San_dOria/npcs/Cletae.lua"]={["Path"]="scripts/zones/Southern_San_dOria/npcs/Cletae.lua",["SHA256"]="1115bcb33ee5516f6678a234db0583cd96bb57d2c682421a324c8d50cc25e956",["Text"]="-----------------------------------\n-- Area: Southern San d'Oria\n--  NPC: Cletae\n-- Guild Merchant NPC: Leathercrafting Guild\n-- !pos -189.142 -8.800 14.449 230\n-----------------------------------\nlocal ID = zones[xi.zone.SOUTHERN_SAN_DORIA]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    -- Flyers_For_Regine needs to be reviewed.\n    local flyerForRegine = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.FLYERS_FOR_REGINE)\n\n    if flyerForRegine == 1 then\n        if npcUtil.tradeHasExactly(trade, xi.item.MAGICMART_FLYER) then\n            player:messageSpecial(ID.text.FLYER_REFUSED)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local guildSkillId = xi.skill.LEATHERCRAFT\n    xi.shop.generalGuild(player, xi.shop.generalGuildStock[guildSkillId], guildSkillId)\n    player:showText(npc, ID.text.CLETAE_DIALOG)\nend\n\nreturn entity\n"},["scripts/zones/Southern_San_dOria/npcs/Diary.lua"]={["Path"]="scripts/zones/Southern_San_dOria/npcs/Diary.lua",["SHA256"]="e0b1e4c965600d4b342594e48fe7c85b696c2b4216741566122e064ed8663f17",["Text"]="-----------------------------------\n-- Area: South San d'Oria\n--  NPC: Diary\n-- Involved in Quest: To Cure a Cough, Over The Hills And Far Away\n-- !pos -75 -12 65 230\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local aSquiresTestII = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_SQUIRES_TEST_II)\n    local medicineWoman = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_MEDICINE_WOMAN)\n    local toCureaCough = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.TO_CURE_A_COUGH)\n    local diaryPage = player:getCharVar('DiaryPage')\n\n    if diaryPage == 0 then\n        player:startEvent(639)          -- see diary, option to read (reads page 1)\n    elseif diaryPage == 1 then\n        player:startEvent(640)          -- reads page 2\n    elseif diaryPage == 2 then\n        if\n            medicineWoman == xi.questStatus.QUEST_COMPLETED and\n            aSquiresTestII == xi.questStatus.QUEST_COMPLETED\n        then\n            if toCureaCough == xi.questStatus.QUEST_ACCEPTED then\n                player:startEvent(641)  -- reads page 3\n            else\n                player:startEvent(640)  -- reads page 2\n            end\n        elseif\n            medicineWoman == xi.questStatus.QUEST_AVAILABLE and\n            aSquiresTestII == xi.questStatus.QUEST_AVAILABLE\n        then\n            player:startEvent(641)      -- reads page 3\n        else\n            player:startEvent(640)      -- reads page 2\n        end\n    elseif diaryPage >= 3 then\n        player:startEvent(722)          -- reads page 4\n    --elseif diaryPage >= 4 then\n    --    player:startEvent(723)        -- read last page\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    local diaryPage = player:getCharVar('DiaryPage')\n\n    if option >= diaryPage then\n        if csid == 639 and option == 0 then\n            player:setCharVar('DiaryPage', 1)    -- has read page 1\n        elseif csid == 640 and option == 2 then\n            player:setCharVar('DiaryPage', 2)    -- has read page 2\n        elseif csid == 641 and option == 3 then\n            player:setCharVar('DiaryPage', 3)    -- has read page 3\n        elseif csid == 722 and option == 4 then\n            player:setCharVar('DiaryPage', 4)    -- has read page 4\n        --elseif csid == 723 and option == 5 then\n        --    player:setCharVar('DiaryPage', 5)    -- has read the last page\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Southern_San_dOria/npcs/Gondebaud.lua"]={["Path"]="scripts/zones/Southern_San_dOria/npcs/Gondebaud.lua",["SHA256"]="54a16ba844bdd93e5f988f3062206bbe7a28d038ff1b54910a4e91e44548c276",["Text"]="-----------------------------------\n-- Area: Southern San d'Oria\n--  NPC: Gondebaud\n-- Trust NPC\n-- !pos 123.754 0.000 92.125 230\n-----------------------------------\nlocal ID = zones[xi.zone.SOUTHERN_SAN_DORIA]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    xi.trust.onTradeCipher(player, trade, 3503, 3552, 3553)\nend\n\nentity.onTrigger = function(player, npc)\n    local trustSandoria = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRUST_SANDORIA)\n    local trustBastok   = player:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.TRUST_BASTOK)\n    local trustWindurst = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TRUST_WINDURST)\n\n    if\n        player:getMainLvl() >= 5 and\n        xi.settings.main.ENABLE_TRUST_QUESTS == 1 and\n        trustSandoria == xi.questStatus.QUEST_AVAILABLE\n    then\n        if\n            trustWindurst == xi.questStatus.QUEST_AVAILABLE and\n            trustBastok == xi.questStatus.QUEST_AVAILABLE\n        then\n            player:startEvent(3500)\n        elseif\n            trustWindurst == xi.questStatus.QUEST_COMPLETED or\n            trustBastok == xi.questStatus.QUEST_COMPLETED\n        then\n            player:startEvent(3504)\n        end\n    elseif player:hasKeyItem(xi.keyItem.RED_INSTITUTE_CARD) then\n        player:startEvent(3501)\n    elseif trustSandoria == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(3502)\n    else\n        player:startEvent(3505)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if (csid == 3500 or csid == 3504) and option == 2 then\n        player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRUST_SANDORIA)\n        npcUtil.giveKeyItem(player, xi.keyItem.RED_INSTITUTE_CARD)\n    elseif csid == 3503 or csid == 3553 then\n        local spellID = player:getLocalVar('TradingTrustCipher')\n        player:setLocalVar('TradingTrustCipher', 0)\n        player:addSpell(spellID, { silentLog = true })\n        player:messageSpecial(ID.text.YOU_LEARNED_TRUST, 0, spellID)\n        player:tradeComplete()\n    end\nend\n\nreturn entity\n"},["scripts/zones/Southern_San_dOria/npcs/Kipopo.lua"]={["Path"]="scripts/zones/Southern_San_dOria/npcs/Kipopo.lua",["SHA256"]="48c8751f8e22768ce119c088ddb93be7937c2b29b35bfa6d815c6d95744c8726",["Text"]="-----------------------------------\n-- Area: Southern San d'Oria\n--  NPC: Kipopo\n-- Type: Leathercraft Synthesis Image Support\n-- !pos -191.050 -2.15 12.285 230\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:hasKeyItem(xi.keyItem.TORN_PATCHES_OF_LEATHER) and\n        player:getCharVar('sayItWithAHandbagCS') == 2 and\n        npcUtil.tradeHasExactly(trade, { 2012, 850, 816 })\n    then\n        player:startEvent(910)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local sayItWithAHandbagCS = player:getCharVar('sayItWithAHandbagCS')\n\n    if\n        player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.SAY_IT_WITH_A_HANDBAG) == xi.questStatus.QUEST_COMPLETED and\n        player:getCharVar('sayItWithAHandbagBonusCS') == 1\n    then\n        player:startEvent(914)\n\n    elseif\n        player:hasKeyItem(xi.keyItem.REPAIRED_HANDBAG) and\n        sayItWithAHandbagCS == 4\n    then\n        player:startEvent(913)\n\n    elseif sayItWithAHandbagCS == 3 then\n        if player:needToZone() then\n            player:startEvent(911)\n        else\n            player:startEvent(912)\n        end\n\n    elseif sayItWithAHandbagCS == 2 then\n        player:startEvent(909)\n\n    elseif\n        player:hasKeyItem(xi.keyItem.TORN_PATCHES_OF_LEATHER) and\n        sayItWithAHandbagCS == 1\n    then\n        player:startEvent(908)\n\n    else\n        xi.crafting.oldImageSupportOnTrigger(player, npc)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 914 then\n        player:setCharVar('sayItWithAHandbagBonusCS', 0)\n    elseif csid == 912 then\n        npcUtil.giveKeyItem(player, xi.keyItem.REPAIRED_HANDBAG)\n        player:setCharVar('sayItWithAHandbagCS', 4)\n    elseif csid == 910 then\n        player:delKeyItem(xi.keyItem.TORN_PATCHES_OF_LEATHER)\n        player:setCharVar('sayItWithAHandbagCS', 3)\n        player:needToZone(true)\n        player:confirmTrade()\n    elseif csid == 908 and option == 1 then\n        player:setCharVar('sayItWithAHandbagCS', 2)\n    else\n        xi.crafting.oldImageSupportOnEventFinish(player, csid, option, npc)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Southern_San_dOria/npcs/Nenne.lua"]={["Path"]="scripts/zones/Southern_San_dOria/npcs/Nenne.lua",["SHA256"]="db6e6c675b0ac82bd7fd71f9ce6c41d95d24e8da1c14f79884f63a555a21c41e",["Text"]="-----------------------------------\n-- Area: Southern San d'Oria\n--  NPC: Nenne\n-- Starts and Finishes Quest: To Cure a Cough\n-- !pos -114 -6 102 230\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local medicineWoman = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_MEDICINE_WOMAN)\n    local toCureaCough = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.TO_CURE_A_COUGH)\n\n    if\n        toCureaCough == xi.questStatus.QUEST_AVAILABLE and\n        player:getCharVar('toCureaCough') == 0 and\n        medicineWoman == xi.questStatus.QUEST_COMPLETED\n    then\n        player:startEvent(538)\n    elseif player:hasKeyItem(xi.keyItem.COUGH_MEDICINE) then\n        player:startEvent(647)\n    else\n        player:startEvent(584)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 538 then\n        player:setCharVar('toCureaCough', 1)\n    elseif csid == 647 then\n        player:addTitle(xi.title.A_MOSS_KIND_PERSON)\n        player:setCharVar('toCureaCough', 0)\n        player:delKeyItem(xi.keyItem.COUGH_MEDICINE)\n        npcUtil.giveKeyItem(player, xi.keyItem.SCROLL_OF_TREASURE)\n        player:addFame(xi.fameArea.SANDORIA, 30)\n        player:completeQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.TO_CURE_A_COUGH)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Southern_San_dOria/npcs/Sharzalion.lua"]={["Path"]="scripts/zones/Southern_San_dOria/npcs/Sharzalion.lua",["SHA256"]="f76f20081ef9136186835f002242e414ec6fc27edf9baa614da98a5d00e316ff",["Text"]="-----------------------------------\n-- Area: Southern San d'Oria\n--  NPC: Sharzalion\n-- !pos 95 0 111 230\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local envelopedInDarkness = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.ENVELOPED_IN_DARKNESS)\n    local peaceForTheSpirit   = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.PEACE_FOR_THE_SPIRIT)\n    local peaceForTheSpiritCS = player:getCharVar('peaceForTheSpiritCS')\n\n    if\n        envelopedInDarkness == xi.questStatus.QUEST_COMPLETED and\n        peaceForTheSpirit == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(69)\n    elseif\n        peaceForTheSpirit == xi.questStatus.QUEST_ACCEPTED and\n        peaceForTheSpiritCS == 0\n    then\n        player:startEvent(64)\n    elseif\n        peaceForTheSpirit == xi.questStatus.QUEST_ACCEPTED and\n        peaceForTheSpiritCS == 1\n    then\n        player:startEvent(65)\n    elseif\n        peaceForTheSpirit == xi.questStatus.QUEST_ACCEPTED and\n        (peaceForTheSpiritCS == 2 or peaceForTheSpiritCS == 3)\n    then\n        player:startEvent(66)\n    else\n        player:startEvent(15)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 64 then\n        player:setCharVar('peaceForTheSpiritCS', 1)\n    elseif csid == 66 then\n        player:setCharVar('peaceForTheSpiritCS', 3)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Southern_San_dOria/npcs/Varchet.lua"]={["Path"]="scripts/zones/Southern_San_dOria/npcs/Varchet.lua",["SHA256"]="c8a6726bbe40c25e0603e94877a9cc0fa1a1ae61e0c796b1e7db6da561083262",["Text"]="-----------------------------------\n-- Area: Southern San d'Oria\n--  NPC: Varchet\n-- !pos 116.484 -1 91.554 230\n-----------------------------------\nlocal ID = zones[xi.zone.SOUTHERN_SAN_DORIA]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal gameWon  = 0\nlocal gameLost = 2\nlocal gameTie  = 3\n\nentity.onTrade = function(player, npc, trade)\n    if npcUtil.tradeHas(trade, { { 'gil', 5 } }) then\n        player:confirmTrade()\n\n        local vdie1 = math.randomInt(1, 6)\n        local vdie2 = math.randomInt(1, 6)\n        local vtotal = vdie1 + vdie2\n        local pdie1 = math.randomInt(1, 6)\n        local pdie2 = math.randomInt(1, 6)\n        local ptotal = pdie1 + pdie2\n\n        local result = gameLost\n        if ptotal > vtotal then\n            result = gameWon\n        elseif ptotal == vtotal then\n            result = gameTie\n        end\n\n        player:setLocalVar('VarchetGame', result)\n        player:startEvent(519, vdie1, vdie2, vtotal, pdie1, pdie2, ptotal, result)\n    else\n        player:startEvent(608)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 519 then\n        local result = player:getLocalVar('VarchetGame')\n        if result == gameWon then\n            npcUtil.giveCurrency(player, 'gil', 10)\n\n            local eventTarget = player:getEventTarget()\n            if\n                eventTarget and\n                xi.quest.getVar(player, xi.questLog.SANDORIA, xi.quest.id.sandoria.EXIT_THE_GAMBLER, 'Stage') == 1\n            then\n                xi.quest.setVar(player, xi.questLog.SANDORIA, xi.quest.id.sandoria.EXIT_THE_GAMBLER, 'Prog', 1)\n                player:showText(eventTarget, ID.text.VARCHET_KEEP_PROMISE) -- Repeats everytime the player wins until the quest is complete\n            end\n        elseif result == gameTie then\n            npcUtil.giveCurrency(player, 'gil', 5)\n        else\n            player:messageSpecial(ID.text.VARCHET_BET_LOST)\n        end\n\n        player:setLocalVar('VarchetGame', 0)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Southern_San_dOria/npcs/Vemalpeau.lua"]={["Path"]="scripts/zones/Southern_San_dOria/npcs/Vemalpeau.lua",["SHA256"]="48547f58185b8cdd9dc8161bdd99af3301f76bcc4f10e11453ea88328b868eca",["Text"]="-----------------------------------\n-- Area: Southern San d'Oria\n--  NPC: Vemalpeau\n-- Involved in Quests: Under Oath\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.UNDER_OATH) == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('UnderOathCS') == 0\n    then   -- Quest: Under Oath - PLD AF3\n        player:startEvent(7) --Under Oath - mentions the boy missing\n    elseif\n        player:getCharVar('UnderOathCS') == 3 and\n        player:hasKeyItem(xi.keyItem.MIQUES_PAINTBRUSH)\n    then\n        player:startEvent(5) --Under Oath - upset about the paintbrush\n    elseif\n        player:getCharVar('UnderOathCS') == 4 and\n        player:hasKeyItem(xi.keyItem.STRANGE_SHEET_OF_PAPER)\n    then\n        player:startEvent(3) -- Under Oath - mentions commanding officer\n    elseif\n        player:getCharVar('UnderOathCS') == 9 and\n        player:hasKeyItem(xi.keyItem.KNIGHTS_CONFESSION)\n    then\n        player:startEvent(2) -- Under Oath - Thanks you and concludes quest\n    else\n        player:startEvent(1)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 7 then\n        player:setCharVar('UnderOathCS', 1)\n    elseif csid == 5 then\n        player:setCharVar('UnderOathCS', 4)\n        player:delKeyItem(xi.keyItem.MIQUES_PAINTBRUSH)\n    elseif csid == 2 then\n        player:setCharVar('UnderOathCS', 0)\n        player:delKeyItem(xi.keyItem.KNIGHTS_CONFESSION)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Southern_San_dOria_[S]/npcs/Thierride.lua"]={["Path"]="scripts/zones/Southern_San_dOria_[S]/npcs/Thierride.lua",["SHA256"]="a871dc2e725b726a2b12e02e451ceb76fbc051019ed5d39cdee9eb29f1b1fda2",["Text"]="-----------------------------------\n-- Area: Southern SandOria [S]\n--  NPC: Thierride\n-- !pos -124 -2 14 80\n-----------------------------------\nlocal ID = zones[xi.zone.SOUTHERN_SAN_DORIA_S]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\n-- Item 1019 = Lufet Salt\n-- Had to use setCharVar because you have to trade Salts one at a time according to the wiki.\n-- Lufet Salt can be obtained by killing Crabs in normal West Ronfaure.\n\nentity.onTrade = function(player, npc, trade)\n    local lufetSalt = trade:hasItemQty(xi.item.CHUNK_OF_LUFET_SALT, 1)\n    local cnt = trade:getItemCount()\n    local beansAhoy = player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BEANS_AHOY)\n\n    if lufetSalt and cnt == 1 and beansAhoy == xi.questStatus.QUEST_ACCEPTED then\n        if player:getCharVar('BeansAhoy') == 0 then\n            player:startEvent(337) -- Traded the Correct Item Dialogue (NOTE: You have to trade the Salts one at according to wiki)\n        elseif not player:needToZone() then\n            player:startEvent(340) -- Quest Complete Dialogue\n        end\n    else\n        player:startEvent(339) -- Wrong Item Traded\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local beansAhoy = player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BEANS_AHOY)\n\n    if beansAhoy == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(334) -- Quest Start\n    elseif beansAhoy == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(335) -- Quest Active, NPC Repeats what he says but as normal 'text' instead of cutscene.\n    elseif\n        beansAhoy == xi.questStatus.QUEST_COMPLETED and\n        player:getCharVar('BeansAhoy_ConquestWeek') == 0\n    then\n        player:startEvent(342)\n    elseif beansAhoy == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(341)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 334 then\n        player:addQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BEANS_AHOY)\n    elseif csid == 337 then\n        player:tradeComplete()\n        player:setCharVar('BeansAhoy', 1)\n        player:needToZone(true)\n    elseif csid == 340 or csid == 342 then\n        if\n            player:hasItem(xi.item.ANGLERS_CASSOULET, 1) or\n            player:getFreeSlotsCount() < 1\n        then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.ANGLERS_CASSOULET)\n        else\n            player:addItem(xi.item.ANGLERS_CASSOULET, 1)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.ANGLERS_CASSOULET)\n            player:setCharVar('BeansAhoy_ConquestWeek', 1, NextConquestTally())\n            if csid == 340 then\n                player:completeQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BEANS_AHOY)\n                player:setCharVar('BeansAhoy', 0)\n                player:tradeComplete()\n            end\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Tavnazian_Safehold/npcs/Ferchinne.lua"]={["Path"]="scripts/zones/Tavnazian_Safehold/npcs/Ferchinne.lua",["SHA256"]="5ccfa8fe033123ade14cd8b89282639535e92fc78417207da3c86176f0f6cb24",["Text"]="-----------------------------------\n-- Area: Tavnazian Safehold\n--  NPC: Ferchinne\n-- Note: Involved in quest: \"Fly High\"\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local flyHigh = player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.FLY_HIGH)\n\n    if\n        flyHigh == xi.questStatus.QUEST_ACCEPTED and\n        npcUtil.tradeHas(trade, { { xi.item.HIPPOGRYPH_TAILFEATHER, 2 } })\n    then\n        -- 2x Hippogryph Tailfeather\n        player:startEvent(243)\n    elseif\n        flyHigh == xi.questStatus.QUEST_COMPLETED and\n        npcUtil.tradeHas(trade, { { xi.item.HIPPOGRYPH_TAILFEATHER, 2 } })\n    then\n        -- 2x Hippogryph Tailfeather\n        player:startEvent(245)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getCurrentMission(xi.mission.log_id.COP) == xi.mission.id.cop.THE_SAVAGE or\n        player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.THE_SAVAGE)\n    then\n        local flyHigh = player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.FLY_HIGH)\n\n        if flyHigh == xi.questStatus.QUEST_AVAILABLE then\n            player:startEvent(241)\n        elseif flyHigh == xi.questStatus.QUEST_ACCEPTED then\n            player:startEvent(242)\n        elseif flyHigh == xi.questStatus.QUEST_COMPLETED then\n            player:startEvent(244)\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 241 then\n        player:addQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.FLY_HIGH)\n    elseif\n        csid == 243 and\n        npcUtil.completeQuest(player, xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.FLY_HIGH, { item = xi.item.MISTMELT })\n    then\n        -- Mistmelt\n        player:confirmTrade()\n    elseif csid == 245 and npcUtil.giveItem(player, xi.item.MISTMELT) then -- Mistmelt\n        player:confirmTrade()\n    end\nend\n\nreturn entity\n"},["scripts/zones/Tavnazian_Safehold/npcs/Meret.lua"]={["Path"]="scripts/zones/Tavnazian_Safehold/npcs/Meret.lua",["SHA256"]="6a6845e8cbe3d65c86244428bdcef49c2e2d6c03d4d3405ac0ac85bed873ed1d",["Text"]="-----------------------------------\n-- Area: Tavnazian Safehold\n--  NPC: Meret\n-- !pos 83.166 -25.082 4.633 26\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\n-- [tradedItemId] = rewardItemId\nlocal trades =\n{\n    [xi.item.SAMPLE_OF_LUMINIAN_TISSUE] = xi.item.VIRTUE_STONE_POUCH,\n    [xi.item.PHUABO_ORGAN]              = xi.item.VIRTUE_STONE_POUCH,\n    [xi.item.XZOMIT_ORGAN]              = xi.item.VIRTUE_STONE_POUCH,\n    [xi.item.AERN_ORGAN]                = xi.item.VIRTUE_STONE_POUCH,\n    [xi.item.HPEMDE_ORGAN]              = xi.item.VIRTUE_STONE_POUCH,\n    [xi.item.YOVRA_ORGAN]               = xi.item.VIRTUE_STONE_POUCH,\n    [xi.item.EUVHI_ORGAN]               = xi.item.VIRTUE_STONE_POUCH,\n    [xi.item.LUMINION_CHIP]             = xi.item.VIRTUE_STONE_POUCH,\n    [xi.item.VICE_OF_ANTIPATHY]         = xi.item.MERCIFUL_CAPE,\n    [xi.item.VICE_OF_AVARICE]           = xi.item.ALTRUISTIC_CAPE,\n    [xi.item.VICE_OF_ASPERSION]         = xi.item.ASTUTE_CAPE,\n    [xi.item.AURA_OF_ADULATION]         = xi.item.NOVIO_EARRING,\n    [xi.item.AURA_OF_VORACITY]          = xi.item.NOVIA_EARRING,\n    [xi.item.SIN_OF_INDIGNATION]        = xi.item.NINURTAS_SASH,\n    [xi.item.SIN_OF_INDOLENCE]          = xi.item.AUREOLE,\n    [xi.item.SIN_OF_INDULGENCE]         = xi.item.FUTSUNO_MITAMA,\n    [xi.item.SIN_OF_INVIDIOUSNESS]      = xi.item.RAPHAELS_ROD,\n    [xi.item.SIN_OF_INSOLENCE]          = xi.item.MARSS_RING,\n    [xi.item.SIN_OF_INFATUATION]        = xi.item.BELLONAS_RING,\n    [xi.item.SIN_OF_INTEMPERANCE]       = xi.item.MINERVAS_RING,\n}\n\nentity.onTrade = function(player, npc, trade)\n    if player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.IN_THE_NAME_OF_SCIENCE) == xi.questStatus.QUEST_COMPLETED then\n        for k, v in pairs(trades) do\n            if npcUtil.tradeHasExactly(trade, k) then\n                player:setLocalVar('meretReward', v)\n                player:startEvent(586, k, v)\n                break\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if player:getCurrentMission(xi.mission.log_id.COP) > xi.mission.id.cop.THE_WARRIORS_PATH then\n        if player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.IN_THE_NAME_OF_SCIENCE) == xi.questStatus.QUEST_COMPLETED then\n            if math.randomInt(1, 100) <= 50 then\n                player:startEvent(582)\n            else\n                player:startEvent(583)\n            end\n        else\n            player:startEvent(585)\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 586 and option == player:getLocalVar('meretReward') then\n        player:setLocalVar('meretReward', 0)\n\n        if npcUtil.giveItem(player, option) then\n            player:confirmTrade()\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Tavnazian_Safehold/npcs/Yurim.lua"]={["Path"]="scripts/zones/Tavnazian_Safehold/npcs/Yurim.lua",["SHA256"]="779566770dd0bf5df8692892ad7b193487976ee6dc5843f46f240f58ce720a26",["Text"]="-----------------------------------\n-- Area: Tavnazian Safehold\n--  NPC: Yurim\n-- !pos 83.697 -25.000 3.250 26\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal nosTrades =\n{\n    [xi.item.KARIN_OBI] =\n    {\n        hint = 1,\n        base =\n        {\n            xi.item.SILVER_OBI,\n            xi.item.RED_CHIP,\n        },\n        organs =\n        {\n            { xi.item.PHUABO_ORGAN,              7 },\n            { xi.item.XZOMIT_ORGAN,              3 },\n            { xi.item.SAMPLE_OF_LUMINIAN_TISSUE, 3 },\n        },\n    },\n\n    [xi.item.HYORIN_OBI] =\n    {\n        hint = 2,\n        base =\n        {\n            xi.item.SILVER_OBI,\n            xi.item.CLEAR_CHIP,\n        },\n        organs =\n        {\n            { xi.item.XZOMIT_ORGAN,              7 },\n            { xi.item.PHUABO_ORGAN,              3 },\n            { xi.item.SAMPLE_OF_LUMINIAN_TISSUE, 3 },\n        },\n    },\n\n    [xi.item.FURIN_OBI] =\n    {\n        hint = 3,\n        base =\n        {\n            xi.item.SILVER_OBI,\n            xi.item.GREEN_CHIP,\n        },\n        organs =\n        {\n            { xi.item.AERN_ORGAN,                7 },\n            { xi.item.HPEMDE_ORGAN,              3 },\n            { xi.item.SAMPLE_OF_LUMINIAN_TISSUE, 3 },\n        },\n    },\n\n    [xi.item.DORIN_OBI] =\n    {\n        hint = 4,\n        base =\n        {\n            xi.item.SILVER_OBI,\n            xi.item.YELLOW_CHIP,\n        },\n        organs =\n        {\n            { xi.item.HPEMDE_ORGAN,              7 },\n            { xi.item.AERN_ORGAN,                3 },\n            { xi.item.SAMPLE_OF_LUMINIAN_TISSUE, 3 },\n        },\n    },\n\n    [xi.item.RAIRIN_OBI] =\n    {\n        hint = 5,\n        base =\n        {\n            xi.item.SILVER_OBI,\n            xi.item.PURPLE_CHIP,\n        },\n        organs =\n        {\n            { xi.item.PHUABO_ORGAN,              7 },\n            { xi.item.HPEMDE_ORGAN,              3 },\n            { xi.item.SAMPLE_OF_LUMINIAN_TISSUE, 3 },\n        },\n    },\n\n    [xi.item.SUIRIN_OBI] =\n    {\n        hint = 6,\n        base =\n        {\n            xi.item.SILVER_OBI,\n            xi.item.BLUE_CHIP,\n        },\n        organs =\n        {\n            { xi.item.HPEMDE_ORGAN,              7 },\n            { xi.item.PHUABO_ORGAN,              3 },\n            { xi.item.SAMPLE_OF_LUMINIAN_TISSUE, 3 },\n        },\n    },\n\n    [xi.item.KORIN_OBI] =\n    {\n        hint = 7,\n        base =\n        {\n            xi.item.SILVER_OBI,\n            xi.item.WHITE_CHIP,\n        },\n        organs =\n        {\n            { xi.item.XZOMIT_ORGAN,              7 },\n            { xi.item.AERN_ORGAN,                3 },\n            { xi.item.SAMPLE_OF_LUMINIAN_TISSUE, 3 },\n        },\n    },\n\n    [xi.item.ANRIN_OBI] =\n    {\n        hint = 8,\n        base =\n        {\n            xi.item.SILVER_OBI,\n            xi.item.BLACK_CHIP,\n        },\n        organs =\n        {\n            { xi.item.AERN_ORGAN,                7 },\n            { xi.item.XZOMIT_ORGAN,              3 },\n            { xi.item.SAMPLE_OF_LUMINIAN_TISSUE, 3 },\n        },\n    },\n\n    [xi.item.FLAME_GORGET] =\n    {\n        hint = 9,\n        base =\n        {\n            xi.item.GORGET,\n            xi.item.RED_CHIP,\n        },\n        organs =\n        {\n            { xi.item.PHUABO_ORGAN, 10 },\n            { xi.item.XZOMIT_ORGAN,  5 },\n            { xi.item.YOVRA_ORGAN,   1 },\n        },\n    },\n\n    [xi.item.SNOW_GORGET] =\n    {\n        hint = 10,\n        base =\n        {\n            xi.item.GORGET,\n            xi.item.CLEAR_CHIP,\n        },\n        organs =\n        {\n            { xi.item.PHUABO_ORGAN, 10 },\n            { xi.item.AERN_ORGAN,    5 },\n            { xi.item.YOVRA_ORGAN,   1 },\n        },\n    },\n\n    [xi.item.BREEZE_GORGET] =\n    {\n        hint = 11,\n        base =\n        {\n            xi.item.GORGET,\n            xi.item.GREEN_CHIP,\n        },\n        organs =\n        {\n            { xi.item.PHUABO_ORGAN, 10 },\n            { xi.item.HPEMDE_ORGAN,  5 },\n            { xi.item.YOVRA_ORGAN,   1 },\n        },\n    },\n\n    [xi.item.SOIL_GORGET] =\n    {\n        hint = 12,\n        base =\n        {\n            xi.item.GORGET,\n            xi.item.YELLOW_CHIP,\n        },\n        organs =\n        {\n            { xi.item.XZOMIT_ORGAN, 10 },\n            { xi.item.AERN_ORGAN,    5 },\n            { xi.item.YOVRA_ORGAN,   1 },\n        },\n    },\n\n    [xi.item.THUNDER_GORGET] =\n    {\n        hint = 13,\n        base =\n        {\n            xi.item.GORGET,\n            xi.item.PURPLE_CHIP,\n        },\n        organs =\n        {\n            { xi.item.XZOMIT_ORGAN, 10 },\n            { xi.item.HPEMDE_ORGAN,  5 },\n            { xi.item.YOVRA_ORGAN,   1 },\n        },\n    },\n\n    [xi.item.AQUA_GORGET]  =\n    {\n        hint = 14,\n        base =\n        {\n            xi.item.GORGET,\n            xi.item.BLUE_CHIP,\n        },\n        organs =\n        {\n            { xi.item.AERN_ORGAN,   10 },\n            { xi.item.HPEMDE_ORGAN,  5 },\n            { xi.item.YOVRA_ORGAN,   1 },\n        },\n    },\n\n    [xi.item.LIGHT_GORGET] =\n    {\n        hint = 15,\n        base =\n        {\n            xi.item.GORGET,\n            xi.item.WHITE_CHIP,\n        },\n        organs =\n        {\n            { xi.item.AERN_ORGAN,   7 },\n            { xi.item.PHUABO_ORGAN, 3 },\n            { xi.item.HPEMDE_ORGAN, 3 },\n            { xi.item.YOVRA_ORGAN,  2 },\n        },\n    },\n\n    [xi.item.SHADOW_GORGET] =\n    {\n        hint = 16,\n        base =\n        {\n            xi.item.GORGET,\n            xi.item.BLACK_CHIP,\n        },\n        organs =\n        {\n            { xi.item.HPEMDE_ORGAN, 7 },\n            { xi.item.PHUABO_ORGAN, 3 },\n            { xi.item.AERN_ORGAN,   3 },\n            { xi.item.YOVRA_ORGAN,  2 },\n        },\n    },\n\n    [xi.item.SANATIVE_EARRING] =\n    {\n        hint = 17,\n        base =\n        {\n            xi.item.SILVER_EARRING,\n            xi.item.WHITE_CHIP,\n        },\n        organs =\n        {\n            { xi.item.SAMPLE_OF_LUMINIAN_TISSUE, 5 },\n            { xi.item.EUVHI_ORGAN,               5 },\n        },\n    },\n\n    [xi.item.RELAXING_EARRING] =\n    {\n        hint = 17,\n        base =\n        {\n            xi.item.SILVER_EARRING,\n            xi.item.BLACK_CHIP,\n        },\n        organs =\n        {\n            { xi.item.SAMPLE_OF_LUMINIAN_TISSUE, 5 },\n            { xi.item.EUVHI_ORGAN,               5 },\n        },\n    },\n}\n\nentity.onTrade = function(player, npc, trade)\n    local nameOfScience  = player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.IN_THE_NAME_OF_SCIENCE)\n    local itemInProgress = player:getCharVar('NAME_OF_SCIENCE_target')\n\n    if\n        itemInProgress > 0 and\n        npcUtil.tradeHas(trade, nosTrades[itemInProgress].organs)\n    then\n        player:startEvent(529, xi.item.GORGET, xi.item.SILVER_EARRING, xi.item.SILVER_OBI)\n    elseif\n        (nameOfScience == xi.questStatus.QUEST_ACCEPTED or nameOfScience == xi.questStatus.QUEST_COMPLETED) and\n        npcUtil.tradeHas(trade, xi.item.APPLE_PIE) and\n        itemInProgress > 0\n    then\n        -- apple pie hint\n        player:startEvent(531, xi.item.APPLE_PIE, 0, nosTrades[itemInProgress].hint)\n    elseif\n        (nameOfScience == xi.questStatus.QUEST_ACCEPTED or nameOfScience == xi.questStatus.QUEST_COMPLETED) and\n        itemInProgress == 0\n    then\n        for k, v in pairs(nosTrades) do\n            if npcUtil.tradeHas(trade, v.base) then\n                player:setCharVar('NAME_OF_SCIENCE_target', k)\n                player:startEvent(526, unpack(v.base))\n                break\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    -- IN THE NAME OF SCIENCE\n    if player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.THE_WARRIORS_PATH) then\n        local nameOfScience  = player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.IN_THE_NAME_OF_SCIENCE)\n        local itemInProgress = player:getCharVar('NAME_OF_SCIENCE_target')\n\n        if nameOfScience == xi.questStatus.QUEST_AVAILABLE then\n            player:startEvent(524, xi.item.SILVER_OBI, xi.item.SILVER_EARRING, xi.item.GORGET)\n        elseif\n            (nameOfScience == xi.questStatus.QUEST_ACCEPTED or nameOfScience == xi.questStatus.QUEST_COMPLETED) and\n            itemInProgress == 0\n        then\n            player:startEvent(525, xi.item.SILVER_OBI, xi.item.SILVER_EARRING, xi.item.GORGET)\n        elseif\n            nameOfScience == xi.questStatus.QUEST_ACCEPTED or\n            nameOfScience == xi.questStatus.QUEST_COMPLETED\n        then\n            if math.randomInt(1, 100) <= 30 then\n                player:startEvent(532, unpack(nosTrades[itemInProgress].base))\n            else\n                player:startEvent(528, unpack(nosTrades[itemInProgress].base))\n            end\n        end\n\n    -- STANDARD DIALOG\n    -- TODO: This is not a true default action, and needs to be verified for when this begins to be displayed\n    -- else\n    --    player:startEvent(519)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 524 then\n        player:addQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.IN_THE_NAME_OF_SCIENCE)\n    elseif csid == 531 then\n        player:confirmTrade()\n    elseif csid == 526 then\n        player:confirmTrade()\n    elseif csid == 529 then\n        local itemInProgress = player:getCharVar('NAME_OF_SCIENCE_target')\n        if npcUtil.completeQuest(player, xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.IN_THE_NAME_OF_SCIENCE, { item = itemInProgress, var = { 'NAME_OF_SCIENCE_target' } }) then\n            player:confirmTrade()\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Temple_of_Uggalepih/npcs/qm15.lua"]={["Path"]="scripts/zones/Temple_of_Uggalepih/npcs/qm15.lua",["SHA256"]="082129f82ff4b7f31c1bff99fd5657ab5e2044461c4c02396606fc5de47063a6",["Text"]="-----------------------------------\n-- Area: Temple of Uggalepih\n--  NPC: ???\n-- Involved in Quest: Knight Stalker\n-- !pos 58 1 -70 159\n-----------------------------------\nlocal ID = zones[xi.zone.TEMPLE_OF_UGGALEPIH]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local pet = player:getPet()\n    if\n        player:getCharVar('KnightStalker_Progress') == 4 and\n        player:getCharVar('KnightStalker_Kill') == 0 and\n        player:getMainJob() == xi.job.DRG and\n        pet and\n        pet:getPetID() == xi.petId.WYVERN and\n        npcUtil.popFromQM(player, npc, { ID.mob.CLEUVARION_M_RESOAIX, ID.mob.ROMPAULION_S_CITALLE }, { hide = 0, claim = false })\n    then\n        player:messageSpecial(ID.text.SOME_SORT_OF_CEREMONY + 1) -- Your wyvern reacts violently to this spot!\n    elseif player:getCharVar('KnightStalker_Kill') == 1 then\n        player:startEvent(67)\n    else\n        player:messageSpecial(ID.text.SOME_SORT_OF_CEREMONY)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if\n        csid == 67 and\n        npcUtil.completeQuest(player, xi.questLog.SANDORIA, xi.quest.id.sandoria.KNIGHT_STALKER, { item = 12519, fame = 20, title = xi.title.PARAGON_OF_DRAGOON_EXCELLENCE, var = { 'KnightStalker_Kill', 'KnightStalker_Progress' } })\n    then\n        player:delKeyItem(xi.keyItem.CHALLENGE_TO_THE_ROYAL_KNIGHTS)\n        player:setCharVar('KnightStalker_Option1', 1) -- Optional post-quest cutscenes.\n        player:setCharVar('KnightStalker_Option2', 1)\n    end\nend\n\nreturn entity\n"}};
